import { type } from "arktype";

export const applyTax = type.fn("number", "number=", ":", "number")((amount, taxRate = 0.1) => {
    return amount + (amount * taxRate);
});

console.log(applyTax(100));
console.log(applyTax(100, 0.2));
try {
    applyTax("100" as any, 0.1);
} catch (e) {
    console.error(e.message);
}

export const formatInvoice = type.fn("number[]", "number=", ":", { total: "number", count: "number" })((amounts, discount = 0) => {
    const total = amounts.reduce((sum, a) => sum + a, 0);
    return {
        total: total * (1 - discount),
        count: amounts.length
    };
});

console.log(formatInvoice([10, 20, 30]));
console.log(formatInvoice([10, 20, 30], 0.5));

